from googleapiclient import discovery

def metric_annotation_safety(payload, config=None):
    config = config or {}
    api_key = config.get("perspective_api_key")

    if not api_key:
        raise ValueError("Perspective API key not provided in config.")

    client = discovery.build(
        "commentanalyzer",
        "v1alpha1",
        developerKey=api_key,
        discoveryServiceUrl="https://commentanalyzer.googleapis.com/$discovery/rest?version=v1alpha1",
        static_discovery=False,
    )

    text_to_analyze = payload["annotation_text"]

    analyze_request = {
        'comment': {'text': text_to_analyze},
        'requestedAttributes': {'TOXICITY': {}},
    }

    response = client.comments().analyze(body=analyze_request).execute()

    toxicity_score = response["attributeScores"]["TOXICITY"]["summaryScore"]["value"]

    # A threshold for safety; this can be configured
    is_safe = toxicity_score < config.get("toxicity_threshold", 0.7)

    return {"is_safe": is_safe, "toxicity_score": toxicity_score}

from google.cloud import translate_v3 as translate

def dashboard_note_translate(payload, config=None):
    config = config or {}
    project_id = config.get("project_id")

    client = translate.TranslationServiceClient()

    parent = f"projects/{project_id}/locations/global"

    text_to_translate = payload["note_text"]
    target_language_code = payload["target_locale"]
    source_language_code = payload.get("source_locale") # Optional

    if source_language_code:
        response = client.translate_text(
            request={
                "parent": parent,
                "contents": [text_to_translate],
                "mime_type": "text/plain",
                "source_language_code": source_language_code,
                "target_language_code": target_language_code,
            }
        )
    else:
        response = client.translate_text(
            request={
                "parent": parent,
                "contents": [text_to_translate],
                "mime_type": "text/plain",
                "target_language_code": target_language_code,
            }
        )

    translations = []
    for translation in response.translations:
        translations.append(translation.translated_text)

    return {"translated_notes": translations}
